static z_t2820_t z_t81_lastIndexOf(const z_t81_t* self, const z_t81_t* needle);
static z_t2820_t z_t81_lastIndexOf(const z_t81_t* self, const z_t81_t* needle) {
    z_t2820_t out = {0};
    if (needle->size == 0) {
        out.tag = Z_T2820_TAG_1;
        out.data.a1 = self->size;
        return out;
    }
    if (needle->size > self->size) {
        out.tag = Z_T2820_TAG_0;
        return out;
    }
    for (uint64_t i = self->size - needle->size + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->size) == 0) {
            out.tag = Z_T2820_TAG_1;
            out.data.a1 = idx;
            return out;
        }
    }
    out.tag = Z_T2820_TAG_0;
    return out;
}


